use std::collections::BTreeMap;
use std::{fs, io};

use anyhow::{Context, Result};
use itertools::Itertools;
use serde::{Deserialize, Serialize};

use crate::{build::shims::SerdeHasher, src::perfect_hash::Hasher};

#[derive(Debug, Serialize, Deserialize, Default)]
pub struct TableCacheInfo {
    #[serde(default)]
    cache: Vec<TableCacheEntry>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct TableCacheEntry {
    maps: BTreeMap<String, toml::Value>,

    #[serde(with = "SerdeHasher")]
    hasher: Hasher,
}

const PHCACHE_HEADER: &str = "# Perfect Hash Cache
# auto-generated by `build.rs`
#
# Warning: generating this values can be a lengthy process.
# Beware of editing files in the `src` directory aside `lib.rs` if you are not in for a long wait";

impl TableCacheInfo {
    const PATH: &str = ".phcache";

    pub fn load() -> Result<Self> {
        cargo_emit::rerun_if_changed!(Self::PATH);
        match fs::read(Self::PATH) {
            Ok(str) => toml::from_slice(&str).context("Cannot read perfect hash cache"),
            Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(Self::default()),
            Err(err) => Err(err).context("Cannot read table cache"),
        }
    }

    pub fn save(self) -> Result<()> {
        let contents = toml::to_string(&self).context("Cannot serialize perfect hash cache")?;
        fs::write(Self::PATH, format!("{PHCACHE_HEADER}\n\n{contents}"))
            .context("Cannot save perfect hash cache")
    }

    pub fn get<K, V>(&self, maps: &BTreeMap<K, V>) -> Result<Option<Hasher>>
    where
        K: ToString,
        V: Serialize,
    {
        let serialized = maps
            .iter()
            .map(|(k, v)| toml::Value::try_from(v).map(|v| (k.to_string(), v)))
            .try_collect::<_, BTreeMap<_, _>, _>()?;

        Ok(self
            .cache
            .iter()
            .find(|entry| entry.maps == serialized)
            .map(|entry| entry.hasher))
    }

    pub fn set<K, V>(&mut self, maps: &BTreeMap<K, V>, hasher: Hasher) -> Result<()>
    where
        K: ToString,
        V: Serialize,
    {
        let serialized = maps
            .iter()
            .map(|(k, v)| toml::Value::try_from(v).map(|v| (k.to_string(), v)))
            .try_collect::<_, BTreeMap<_, _>, _>()?;

        if let Some(entry) = self.cache.iter_mut().find(|entry| entry.maps == serialized) {
            entry.hasher = hasher;
        } else {
            self.cache.push(TableCacheEntry {
                maps: serialized,
                hasher,
            });
        };

        Ok(())
    }
}
